// The blocks below are real, completely unmodified Byron mainnet blocks,
// fetched directly from a mainnet relay (backbone.cardano.iog.io:3001) via
// this repo's own chain-sync/block-fetch protocol clients, specifically
// because they carry genuine non-empty SSC payload content. This closes the
// correctness gap flagged in review of the original stateful SSC body-proof
// PR: every other test in sscstate_test.go checks that this package's own
// accumulation reproduces a hash *this package itself* computed, which
// cannot catch a wire-shape or canonicalization bug shared between the
// production code and the test's own expectations. These tests instead
// check the accumulated state against each block's own real header
// ssc_proof, an independent value produced by the real cardano-sl network,
// not by this codebase.
//
// ssc_proof validation itself is entirely block-local (see
// checkSscProofLocal's doc comment): each block below is checked against
// its own real header ssc_proof using only that same block's own SSC
// payload, so none of these fixtures need any other block, embedded or
// not, to validate. AccumulateBlock is exercised on these same blocks too,
// but only to demonstrate ByronEpochSscState's registry-building behavior
// on genuine multi-stakeholder data -- not because ssc_proof validation
// needs it.
//
// Each fixture's own doc comment below records its epoch/slot (the same
// method used to fetch it) and its own block hash, computed here by this
// package's own ByronMainBlock.Hash() -- not merely asserted, but
// cross-checked against the prevBlock field of whichever other embedded
// fixture is chain-adjacent to it, where one exists. A future reviewer can
// independently re-fetch any of these slots from a mainnet relay (or a
// block explorer) and confirm both the raw block content and the recorded
// hash match, rather than relying solely on this package's own hashing
// being internally self-consistent.
const (
	// Epoch 1, slot 21601: epoch 1's first main block. CommitmentsPayload
	// with 1 commitment, no VSS certificates. Fetched via chain-sync from
	// a mainnet relay (backbone.cardano.iog.io:3001) using this repo's own
	// chain-sync/block-fetch protocol clients. This block's own hash --
	// computed here by this package's ByronMainBlock.Hash(), not asserted
	// blindly -- is
	// 84ba3d3e3dac8f574db187074e29605c2512ce65d5022f5e7d07e52620f498b0,
	// independently cross-checked against the prevBlock field embedded in
	// realEpoch1Slot21602Hex below (the very next main block), which
	// carries this same value: a reviewer can re-fetch slot 21601 from any
	// mainnet relay or block explorer and confirm both the block content
	// and this hash.
	realEpoch1Slot21601Hex = ""
	// Epoch 1, slot 21602: CommitmentsPayload with 3 commitments. Same
	// provenance as realEpoch1Slot21601Hex above (chain-sync from
	// backbone.cardano.iog.io:3001 using this repo's own protocol
	// clients). This block's own hash is
	// 719e54f0a72386acc0c0953b54b812bc58876238353cef40b66ee630d1c521da,
	// cross-checked the same way against realEpoch1Slot21603Hex's own
	// prevBlock field below.
	realEpoch1Slot21602Hex = ""
	// Epoch 1, slot 21603: CommitmentsPayload with 3 commitments. Same
	// provenance as realEpoch1Slot21601Hex above. This block's own hash is
	// 1615870f1c9877341e67fe1b8cb1c68a46928ef2f45d849be56e00ff61b72765.
	// This is the last of three consecutive main blocks embedded here
	// (slots 21601, 21602, 21603); no main block exists between any pair
	// of them on the real chain.
	realEpoch1Slot21603Hex = ""
	// Epoch 1, slot 30240: OpeningsPayload with 2 openings. Its own real
	// header ssc_proof is checked entirely from this block's own payload,
	// independent of the three CommitmentsPayload blocks above -- see
	// TestByronEpochSscStateRealMainnet. Same provenance as
	// realEpoch1Slot21601Hex above (chain-sync from
	// backbone.cardano.iog.io:3001). This block's own hash is
	// 5034a7cfc4c7e8203a06289422e42a3996808be17821001b79f0638c1d6aade6; its
	// own prevBlock field is
	// a02811f878adcf5fcb9166d5c9016be843b5be4a11400bdf6c3b707555991c82 --
	// a real main block that exists between slot 21603 and slot 30240 but
	// is not itself embedded here, since ssc_proof validation is
	// block-local and does not need it.
	realEpoch1Slot30240Hex = ""

	// Epoch 6, slot 129601: epoch 6's first main block. CommitmentsPayload
	// with 1 commitment and 7 VSS certificates from 7 distinct
	// stakeholders -- a genuine multi-stakeholder VSS certificate set.
	// Same provenance as realEpoch1Slot21601Hex above (chain-sync from
	// backbone.cardano.iog.io:3001). This block's own hash is
	// caa2ad0acab6e6cbfbaa47042503e59668e8ccda496042e0e2dbd48163e76f17.
	realEpoch6Slot129601Hex = ""
)

// decodeRealMainnetBlock decodes one of the real mainnet block fixtures
// above.
func decodeRealMainnetBlock(t *testing.T, hexStr string) *byron.ByronMainBlock {
	t.Helper()
	raw, err := hex.DecodeString(hexStr)
	require.NoError(t, err)
	block, err := byron.NewByronMainBlockFromCbor(raw)
	require.NoError(t, err)
	return block
}

// tamperSscPayload decodes a real mainnet block, applies mutate to its own
// SSC payload's raw parts ([type, primary, certs] for
// commitments/openings/shares, or [type, certs] for CertificatesPayload),
// and returns a block carrying the mutated payload alongside the
// *original*, now-stale, real header ssc_proof -- demonstrating that a
// real ssc_proof binds to its own block's payload (see
// checkSscProofLocal's doc comment): any change to that payload, without a
// matching change to the header, must be detected.
func tamperSscPayload(
	t *testing.T,
	hexStr string,
	mutate func(parts []cbor.RawMessage) []cbor.RawMessage,
) *byron.ByronMainBlock {
	t.Helper()
	raw, err := hex.DecodeString(hexStr)
	require.NoError(t, err)

	var blockParts []cbor.RawMessage
	_, err = cbor.Decode(raw, &blockParts)
	require.NoError(t, err)
	require.Len(t, blockParts, 3)

	var header []cbor.RawMessage
	_, err = cbor.Decode(blockParts[0], &header)
	require.NoError(t, err)
	require.Len(t, header, 5)
	var bodyProof []cbor.RawMessage
	_, err = cbor.Decode(header[2], &bodyProof)
	require.NoError(t, err)
	require.Len(t, bodyProof, 4)
	originalProof := []byte(bodyProof[1])

	var body []cbor.RawMessage
	_, err = cbor.Decode(blockParts[1], &body)
	require.NoError(t, err)
	require.Len(t, body, 4)

	var sscParts []cbor.RawMessage
	_, err = cbor.Decode(body[1], &sscParts)
	require.NoError(t, err)

	mutatedParts := mutate(sscParts)
	mutatedPayload, err := cbor.Encode(mutatedParts)
	require.NoError(t, err)

	blockCbor := withSscPayloadAndProof(t, raw, mutatedPayload, originalProof)
	block, err := byron.NewByronMainBlockFromCbor(
		blockCbor, common.VerifyConfig{SkipBodyHashValidation: true},
	)
	require.NoError(t, err)
	return block
}

// flipSetEntryFieldByte decodes setRaw as a tag-258 set (ssccomms/ssccerts),
// flips one byte within the first entry's fieldIndex byte-string field, and
// re-encodes -- a minimal, always-CBOR-valid mutation to that entry's
// content (not its shape), so decodeIdentitySet still accepts it but its
// hash changes.
func flipSetEntryFieldByte(
	t *testing.T,
	setRaw cbor.RawMessage,
	fieldIndex int,
) cbor.RawMessage {
	t.Helper()
	var set cbor.SetType[cbor.RawMessage]
	_, err := cbor.Decode(setRaw, &set)
	require.NoError(t, err)
	items := set.Items()
	require.NotEmpty(t, items)

	var fields []cbor.RawMessage
	_, err = cbor.Decode(items[0], &fields)
	require.NoError(t, err)
	if len(fields) <= fieldIndex {
		t.Fatalf(
			"entry has %d fields, need index %d", len(fields), fieldIndex,
		)
	}
	var fieldBytes []byte
	_, err = cbor.Decode(fields[fieldIndex], &fieldBytes)
	require.NoError(t, err)
	require.NotEmpty(t, fieldBytes)
	fieldBytes[0] ^= 0xff
	newField, err := cbor.Encode(fieldBytes)
	require.NoError(t, err)
	fields[fieldIndex] = cbor.RawMessage(newField)

	newItem, err := cbor.Encode(fields)
	require.NoError(t, err)
	items[0] = cbor.RawMessage(newItem)

	newSet := cbor.NewSetType(items, true)
	encoded, err := cbor.Encode(newSet)
	require.NoError(t, err)
	return cbor.RawMessage(encoded)
}

// flipMapEntryValueByte decodes mapRaw as a real CBOR map (sscopens/
// sscshares), flips one byte within one entry's byte-string value, and
// re-encodes.
func flipMapEntryValueByte(
	t *testing.T,
	mapRaw cbor.RawMessage,
) cbor.RawMessage {
	t.Helper()
	var m map[cbor.ByteString]cbor.RawMessage
	_, err := cbor.Decode(mapRaw, &m)
	require.NoError(t, err)
	require.NotEmpty(t, m)
	for k, v := range m {
		var valueBytes []byte
		_, err := cbor.Decode(v, &valueBytes)
		require.NoError(t, err)
		require.NotEmpty(t, valueBytes)
		valueBytes[0] ^= 0xff
		newValue, err := cbor.Encode(valueBytes)
		require.NoError(t, err)
		m[k] = cbor.RawMessage(newValue)
		break
	}
	encoded, err := cbor.Encode(m)
	require.NoError(t, err)
	return cbor.RawMessage(encoded)
}

// TestByronEpochSscStateRealMainnet is the correctness gate requested in
// review of the original stateful SSC body-proof PR: it proves, against
// real mainnet block data rather than this package's own synthetic
// fixtures, that ValidateBodyProof's block-local ssc_proof check reproduces
// each of these four real blocks' own real header ssc_proof, fetched
// directly off the mainnet chain, not a hash this package computed for
// itself -- across a CommitmentsPayload block with 3 distinct
// stakeholders (block3) and an OpeningsPayload block with 2 (block4). It
// also confirms that tampering either block's own commitment/opening entry
// is detected by that same block's own proof.
//
// block1, block2, and block3 are three consecutive real main blocks (no
// other main block exists between them); block4 is a later block in the
// same epoch, not the next main block after block3 -- there are real main
// blocks between block3 and block4 that are not embedded here, since
// ssc_proof validation is block-local and does not need them.
func TestByronEpochSscStateRealMainnet(t *testing.T) {
	block1 := decodeRealMainnetBlock(t, realEpoch1Slot21601Hex)
	block2 := decodeRealMainnetBlock(t, realEpoch1Slot21602Hex)
	block3 := decodeRealMainnetBlock(t, realEpoch1Slot21603Hex)
	block4 := decodeRealMainnetBlock(t, realEpoch1Slot30240Hex)

	// The correctness gate itself: each real block's own ssc_proof, checked
	// entirely from its own payload, validates -- across a
	// CommitmentsPayload block with 3 distinct stakeholders (block3) and an
	// OpeningsPayload block with 2 (block4). This whole file is specifically
	// about confirming the real hash comparison, so every ValidateBodyProof
	// call here opts into it via
	// common.VerifyConfig.EnableByronSscProofHashValidation -- the default,
	// structural-only check would not exercise what these tests exist to
	// prove.
	hashCheckCfg := common.VerifyConfig{EnableByronSscProofHashValidation: true}
	for _, b := range []*byron.ByronMainBlock{block1, block2, block3, block4} {
		assert.NoError(t, b.ValidateBodyProof(hashCheckCfg))
	}

	// AccumulateBlock's registry view still works, for callers who want it,
	// across these four blocks' genuinely non-empty, multi-stakeholder
	// commitments and openings -- this is not required for, or connected
	// to, the ssc_proof validation above (see ByronEpochSscState's doc
	// comment).
	sscState := byron.NewByronEpochSscState()
	require.NoError(t, sscState.AccumulateBlock(block1))
	require.NoError(t, sscState.AccumulateBlock(block2))
	require.NoError(t, sscState.AccumulateBlock(block3))
	require.NoError(t, sscState.AccumulateBlock(block4))
	require.Len(t, sscState.Commitments, 7)
	require.Len(t, sscState.Openings, 2)
	require.Empty(t, sscState.VssCertificates)

	t.Run(
		"tampered commitment is detected by that block's own proof",
		func(t *testing.T) {
			tampered := tamperSscPayload(
				t, realEpoch1Slot21603Hex,
				func(parts []cbor.RawMessage) []cbor.RawMessage {
					parts[1] = flipSetEntryFieldByte(t, parts[1], 2)
					return parts
				},
			)
			err := tampered.ValidateBodyProof(hashCheckCfg)
			require.Error(t, err)
			assert.ErrorIs(t, err, byron.ErrBodyProofMismatch)
		},
	)

	t.Run(
		"tampered opening is detected by that block's own proof",
		func(t *testing.T) {
			tampered := tamperSscPayload(
				t, realEpoch1Slot30240Hex,
				func(parts []cbor.RawMessage) []cbor.RawMessage {
					parts[1] = flipMapEntryValueByte(t, parts[1])
					return parts
				},
			)
			err := tampered.ValidateBodyProof(hashCheckCfg)
			require.Error(t, err)
			assert.ErrorIs(t, err, byron.ErrBodyProofMismatch)
		},
	)
}

// TestByronEpochSscStateRealMainnetCertificates is the same correctness
// gate as TestByronEpochSscStateRealMainnet, applied to a real block whose
// VSS certificate set has multiple (7) distinct stakeholders -- proving
// canonicalMapHash's map encoding (see its doc comment) reproduces the
// real chain's own ssc_proof for genuine multi-stakeholder VSS
// certificates, not just the bundled fixture's trivial empty case, and
// that its own real header ssc_proof also correctly binds its (single)
// commitment.
//
// This block happens to be epoch 6's first main block, so on its own this
// fixture cannot distinguish "this block's own certificate set" from "the
// epoch's accumulated certificate set so far" -- the two are identical at
// that point in the epoch. What establishes that ssc_proof's certificates
// hash is genuinely block-local, not epoch-accumulated, is cardano-sl's
// own type declarations (see checkSscProofLocal's doc comment), not this
// vector by itself.
func TestByronEpochSscStateRealMainnetCertificates(t *testing.T) {
	block := decodeRealMainnetBlock(t, realEpoch6Slot129601Hex)
	// Opt into the full hash comparison: see TestByronEpochSscStateRealMainnet's
	// hashCheckCfg comment for why.
	hashCheckCfg := common.VerifyConfig{EnableByronSscProofHashValidation: true}
	assert.NoError(t, block.ValidateBodyProof(hashCheckCfg))

	sscState := byron.NewByronEpochSscState()
	require.NoError(t, sscState.AccumulateBlock(block))
	require.Len(t, sscState.Commitments, 1)
	require.Len(t, sscState.VssCertificates, 7)

	t.Run("tampered certificate is detected", func(t *testing.T) {
		tampered := tamperSscPayload(
			t, realEpoch6Slot129601Hex,
			func(parts []cbor.RawMessage) []cbor.RawMessage {
				parts[2] = flipSetEntryFieldByte(t, parts[2], 2)
				return parts
			},
		)
		err := tampered.ValidateBodyProof(hashCheckCfg)
		require.Error(t, err)
		assert.ErrorIs(t, err, byron.ErrBodyProofMismatch)
	})

	t.Run("tampered commitment is detected", func(t *testing.T) {
		tampered := tamperSscPayload(
			t, realEpoch6Slot129601Hex,
			func(parts []cbor.RawMessage) []cbor.RawMessage {
				parts[1] = flipSetEntryFieldByte(t, parts[1], 2)
				return parts
			},
		)
		err := tampered.ValidateBodyProof(hashCheckCfg)
		require.Error(t, err)
		assert.ErrorIs(t, err, byron.ErrBodyProofMismatch)
	})
}
